import {showOrdinanceAnalysis} from './ordinance-analysis-ui.js?v=architecture-collection-55';
import {educationServiceDemand} from './education.js?v=architecture-collection-55';
import {DEPARTMENTS,SERVICES} from './civic.js?v=architecture-collection-55';
import {escapeAnnouncement as escape} from './scenario-announcements.js?v=architecture-collection-55';
const advisors={safety:{name:'Maria Montoya',role:'Public safety advisor',portrait:'assets/maria-advisor.png',departments:['police','fire']},hea:{name:'Randall Shoop',role:'Health, education & aura advisor',portrait:'assets/randall-advisor.png',departments:['health','education']}};
export function civicAdvisorBriefing(c,kind){
 const advisor=advisors[kind];if(!advisor)throw Error('Choose a civic advisor.');const s=c.stats,issues=[],add=(title,text,tool,layer)=>issues.push({title,text,tool,layer});
 for(const department of advisor.departments)if(s.strikes.includes(department))add(`${DEPARTMENTS[department]} strike`,'Restore this department to 100% funding and run one month to resume service.');
 if(!s.population)add('A foundation for future residents','There are no residents to serve yet. Connect your first homes to roads and electricity, then plan services as the town grows.','residential','zones');
 else if(kind==='safety'){
  if(s.policeCoverage<50)add('Police coverage',`Average coverage is ${Math.round(s.policeCoverage)}%. Place stations near uncovered homes and check their electricity, roads and funding.`,'police','police');
  if(s.fireCoverage<50)add('Fire preparedness',`Average fire coverage is ${Math.round(s.fireCoverage)}%. Build stations near uncovered homes. Water service also lowers building flammability.`,'fire','fire');
  if((s.serviceCapacities?.jail||0)<s.jailNeed)add('Jail capacity',`${Math.round(s.serviceCapacities?.jail||0)} places are available for an estimated need of ${s.jailNeed}. Jail conditions currently allow ${Math.round((s.jails?.policeEffectiveness??1)*100)}% police effectiveness. Restore inactive jails or add capacity; funding above 100% cannot add cells.`,'jail','crime');
  if(s.averageCrime>25)add('Crime pressure',`Crime averages ${Math.round(s.averageCrime)} out of 100. Neighborhood watch, education and policing can help; inspect the crime map before placing another station.`,'police','crime');
 }else{
  if(s.healthCoverage<60)add('Healthcare access',`Only ${Math.round(s.healthCoverage)}% of residents have hospital access. Connect hospitals to neighborhood roads and electricity, and maintain healthcare funding.`,'hospital','health');
  for(const [type,label,layer]of [['school','Children’s education','schoolAccess'],['college','Young adults’ education','collegeAccess'],['library','Adult learning','adultAccess']]){const demand=educationServiceDemand(c,type);if(demand.share>0&&(s[demand.field]||0)<50)add(label,`${Math.round(s[demand.field]||0)}% have access to the relevant learning places. Schools, colleges and adult facilities serve different age groups; one cannot replace another.`,type,layer);}
  if(s.aura<50)add('Neighborhood wellbeing',`Aura averages ${Math.round(s.aura)} out of 100. Compare local services, crime and pollution; parks can improve nearby residential amenity.`,'park','aura');
 }
 if(!issues.length)add('Maintain the progress',kind==='safety'?'No urgent safety gap crossed these briefing thresholds. Continue checking local coverage and keep emergency services funded.':'No urgent access gap crossed these briefing thresholds. Learning and life expectancy still develop over years; keep services ahead of growth.');
 const facts=kind==='safety'?[['Police coverage',`${Math.round(s.policeCoverage)}%`],['Fire coverage',`${Math.round(s.fireCoverage)}%`],['Average crime',`${Math.round(s.averageCrime)} / 100`]]:[['Life expectancy',`${s.lifeExpectancy.toFixed(1)} years`],['Education',`${Math.round(s.education)} / 100`],['Aura',`${Math.round(s.aura)} / 100`]];
 return {...advisor,issues,facts};
}
export function showCivicAdvisor(ui,kind,back){const d=civicAdvisorBriefing(ui.city(),kind);ui.dialog(d.name,`<div class="civic-advisor-header"><img src="${d.portrait}" width="192" height="192" alt=""><div><p class="eyebrow">${d.role}</p><h3>Your city briefing</h3><p>Based on current service conditions. Open a map to locate the gaps before building.</p></div></div><dl class="civic-advisor-facts">${d.facts.map(([name,value])=>`<div><dt>${name}</dt><dd>${value}</dd></div>`).join('')}</dl>${d.issues.map((issue,i)=>`<article class="civic-advisor-issue"><h3>${escape(issue.title)}</h3><p>${escape(issue.text)}</p><div class="actions">${issue.layer?`<button data-advisor-map="${i}">Inspect map</button>`:''}${issue.tool?`<button data-advisor-build="${i}">Plan ${SERVICES[issue.tool]?.name.toLowerCase()||(issue.tool==='residential'?'homes':'a park')}</button>`:''}</div></article>`).join('')}<button id="advisorPolicies">Compare department ordinances</button><button id="advisorFunding">Review service funding & policies</button><p class="fine">These briefings highlight citywide priorities. Neighborhood conditions may differ.</p>`);document.querySelectorAll('[data-advisor-map]').forEach(b=>b.onclick=()=>{ui.close();ui.setLayer(d.issues[Number(b.dataset.advisorMap)].layer);});document.querySelectorAll('[data-advisor-build]').forEach(b=>b.onclick=()=>{ui.close();ui.setTool(d.issues[Number(b.dataset.advisorBuild)].tool);});document.querySelector('#advisorFunding').onclick=back;document.querySelector('#advisorPolicies').onclick=()=>showOrdinanceAnalysis(ui,kind,()=>showCivicAdvisor(ui,kind,back));}
